import std.fs
import std.thread
from std.sync import Mutex

fn check(path: StrView) -> Result[void]:
    text = fs.read_to_string(path)?
    if text.is_empty():
        return Err(AnyError.msg(owns f"{path} is empty"))
    return Ok(())

fn record(failures: Mutex[Array[AnyError]], owns r: Result[void]):
    match r:
        Ok(_):
            pass
        Err(e):
            with g = failures.lock():
                g.push(owns e)

fn main():
    assets = [String("hero.mesh"), String("sky.tex"), String("level1.cfg")]
    failures: Mutex[Array[AnyError]] = Mutex([])
    with scope = thread.scope():
        for a in assets:
            scope.spawn(owns fn() ref a: record(failures, owns check(a)))
    with g = failures.lock():
        println(g.len(), "assets failed")

class SourceFile:
    name: String
    text: String

@derive(Error)
enum ParseError:
    @error("line {line}: unexpected end of file")
    Truncated(file: shares SourceFile, line: int)

fn parse_header(owns src: shares SourceFile) -> Result[void, ParseError]:
    if src.text.is_empty():
        return Err(ParseError.Truncated(file=src, line=1))
    return Ok(())

fn main() -> Result[void]:
    src = SourceFile(name=String("main.em"), text=String(""))
    parse_header(shares src)?
    println(src.name)
    return Ok(())

class Widget:
    label: String

@derive(Error)
enum LayoutError:
    @error("`{name}` does not fit its parent")
    TooWide(name: String, widget: weakref Widget)

fn check_width(w: Widget, max: int) -> Result[void, LayoutError]:
    if w.label.len() > max:
        return Err(LayoutError.TooWide(name=copy of w.label, widget=weakref w))
    return Ok(())

fn main() -> Result[void]:
    confirm = Widget(label=String("Confirm purchase"))
    check_width(confirm, 8)?
    return Ok(())

