import std.thread

fn count_words(texts: Array[String]) -> int:
    total = 0
    fn count_all():
        for t in texts:
            total += t.split_whitespace().count()
    with scope = thread.scope():
        scope.spawn(count_all)                 # no word: lent to the task
    return total

fn main():
    println(count_words([String("a b"), String("c")]))

